j:if.script:
CustomEvent.observe('user.login', function(user) { 
	if (user.hasRoleFromList('${gs.getProperty('glide.ui.can_search')}')) {
		showObjectInline(gel("textsearch"));
		CustomEvent.fire('adjustsearch');
	} else {
		hideObject(gel("textsearch"));
	}
});

CustomEvent.observe('adjustsearch', adjustSearch);

function adjustSearch() {
	var ajax = new GlideAjax("TextSearchAjax");
	ajax.addParam("sysparm_name", "recent");
	ajax.setWantSessionMessages("false");
	ajax.getXML(adjustSearchResponse);
}

function adjustSearchResponse(request) {
	var answer =  request.responseXML.documentElement.getAttribute("answer");

	if (answer == null)
	return;

	var gcm = new GwtContextMenu('context_search');
	gcm.clear();
	if (answer.indexOf("xyzzyx") != 0) {
		var db = answer.split("^");
		for (var i = 0; i != db.length; i++) {
			var u = new GlideURL('textsearch.do');
			u.addParam('sysparm_search', encodeURIComponent(db[i]));
			u.addParam('sysparm_recent_search','true');
			gcm.addHref(htmlEscape(db[i]), "executeRecentSearch(\""+encodeURIComponent(db[i])+"\",\""+u.getURL()+"\")");
		}
	} else { 
		gcm.addLabel(htmlEscape(answer.substr(6)));
	}
}
